// Danh sách type cần sinh, bắt đầu từ type đầu tiên. Settings.onlyTypes (vd "prefer_day,avoid_day")
// để chạy một phần; để trống = cả 20 type. Tên tab: "[NEW] <type>".
const settings = $('Settings').first().json;
const only = String(settings.onlyTypes || '').split(',').map((s) => s.trim()).filter(Boolean);

const types = $('Dataset Config').first().json.types
  .filter((t) => !only.length || only.includes(t.key))
  .map((t) => ({ ...t, sheetName: `[NEW] ${t.key}` }));
if (!types.length) throw new Error(`onlyTypes "${settings.onlyTypes}" không khớp type nào`);

return [{ json: { types, typeIndex: 0, results: [] } }];

// Type đang sinh, theo typeIndex nhận từ Build Types (lần đầu) hoặc từ Compute Batch (khi chuyển type).
// `results` gom kết quả của các type đã xong, để Summary in ra ở cuối.
const { types } = $('Build Types').first().json;
const { typeIndex, results } = $input.first().json;

return [{ json: { ...types[typeIndex], typeIndex, typeCount: types.length, results: results || [] } }];

// Mỗi vòng lặp: đếm số câu đã có trong tab của type hiện tại, rồi chọn action cho Route:
//   generate  — còn thiếu câu: dựng prompt gồm các slot (mức độ, phạm vi, giá trị) cho AI Agent
//   next_type — type này đã đủ (hoặc quá số lượt): chuyển sang type kế tiếp
//   finished  — hết type
// Slot chỉ để định hướng và kiểm tra câu; workflow không dựng nhãn JSON (việc đó làm ở giai đoạn sau).
const settings = $('Settings').first().json;
const cfg = $('Dataset Config').first().json;
const t = $('Current Type').first().json;

const target = Number(settings.targetPerType) || 200;
const batchSize = Number(settings.batchSize) || 20;
const maxAttempts = Number(settings.maxAttemptsPerType) || 30;

// ---------- Tab hiện tại: Read Rows đọc cột C (sentence), dòng 1 là header ----------
const values = $input.first().json.values || [];
const existing = values.slice(1).map((r) => String((r && r[0]) || '').trim()).filter(Boolean);
const count = existing.length;
const needHeader = values.length === 0;

// Số lượt đã gọi AI cho type này: đọc từ lần chạy gần nhất của "Parse & Validate"
let last = null;
try { last = $('Parse & Validate').first().json; } catch (e) { last = null; }
const attempt = last && last.typeKey === t.key ? last.attempt + 1 : 1;
// Số lượt AI lỗi liên tiếp (tính cả qua các type), Parse & Validate dừng workflow khi vượt ngưỡng
const aiErrorStreak = (last && last.aiErrorStreak) || 0;

const need = Math.max(0, Math.min(batchSize, target - count));
if (need === 0 || attempt > maxAttempts) {
  const results = [...t.results, {
    type: t.key,
    sheet: t.sheetName,
    rows: count,
    aiCalls: attempt - 1,
    status: need === 0 ? 'đủ' : `dừng: quá ${maxAttempts} lượt`,
  }];
  const hasNext = t.typeIndex + 1 < t.typeCount;
  return [{ json: { action: hasNext ? 'next_type' : 'finished', typeIndex: t.typeIndex + 1, results } }];
}
const base = { action: 'generate', typeKey: t.key, count, attempt, need, needHeader, aiErrorStreak };

// ---------- Ngẫu nhiên ----------
const rnd = (n) => Math.floor(Math.random() * n);
const pick = (arr) => arr[rnd(arr.length)];
const weighted = (pairs) => {
  let r = Math.random() * pairs.reduce((s, p) => s + p[1], 0);
  for (const [v, w] of pairs) if ((r -= w) < 0) return v;
  return pairs[pairs.length - 1][0];
};
const seq = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);
const distinct = (k, gen) => { const s = new Set(); while (s.size < k) s.add(gen()); return [...s]; };
const sample = (arr, k) => [...arr].sort(() => Math.random() - 0.5).slice(0, k);

// ---------- Giờ ----------
const toMin = (hm) => { const [h, m] = hm.split(':').map(Number); return h * 60 + m; };
const hhmm = (m) => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
const between = (from, to) => hhmm(toMin(from) + 30 * rnd((toMin(to) - toMin(from)) / 30 + 1));
const later = (hm, lo, hi) => hhmm(Math.min(toMin(hm) + lo + 30 * rnd((hi - lo) / 30 + 1), 18 * 60));
const PERIOD_STARTS = ['07:30', '08:30', '09:30', '10:30', '13:00', '14:00', '15:00'];

// ---------- Thứ ----------
const DAY_ORDER = ['thứ 2', 'thứ 3', 'thứ 4', 'thứ 5', 'thứ 6', 'thứ 7', 'chủ nhật'];
const WEEKDAYS = DAY_ORDER.slice(0, 5);
const SCHOOL_DAYS = DAY_ORDER.slice(0, 6);
const sortDays = (ds) => ds.sort((a, b) => DAY_ORDER.indexOf(a) - DAY_ORDER.indexOf(b));

// ---------- Danh mục môn ----------
const courses = cfg.courses.map(([name, teachers, maxGroup, english]) => ({ name, teachers, maxGroup, english: !!english }));
const pools = {
  all: courses,
  teacher: courses.filter((c) => c.teachers.length),
  group: courses.filter((c) => c.maxGroup >= 2),
  english: courses.filter((c) => c.english && !/tiếng anh/i.test(c.name)),
};

// ---------- Giá trị theo thuộc tính (session = buổi của phạm vi, nếu có) ----------
const GEN = {
  language: () => weighted([['tiếng Anh', 7], ['tiếng Việt', 3]]),
  day: (kind) => (kind === 'prefer'
    ? weighted([
      [() => pick(WEEKDAYS), 60], [() => 'thứ 7', 5],
      [() => sortDays(distinct(2 + rnd(2), () => pick(WEEKDAYS))), 25], [() => 'ngày thường', 10],
    ])
    : weighted([
      [() => pick(WEEKDAYS), 35], [() => 'thứ 7', 20], [() => 'chủ nhật', 8],
      [() => sortDays(distinct(2, () => pick(SCHOOL_DAYS))), 22], [() => 'cuối tuần', 15],
    ]))(),
  session: (kind) => (kind === 'prefer'
    ? weighted([['sáng', 40], ['chiều', 30], ['sáng sớm', 15], ['chiều muộn', 15]])
    : weighted([['sáng', 20], ['chiều', 25], ['sáng sớm', 30], ['chiều muộn', 25]])),
  periods: (kind) => {
    if (kind === 'prefer') {
      const a = 1 + rnd(7);
      const b = Math.min(10, a + 1 + rnd(5));
      return Math.random() < 0.6 ? { min: a, max: b } : seq(a, Math.min(b, a + 3));
    }
    return weighted([
      [() => pick([{ min: 1, max: 2 }, { min: 1, max: 3 }, { min: 9, max: 10 }, { min: 8, max: 10 }, { min: 5, max: 6 }]), 35],
      [() => { const a = 1 + rnd(9); return { min: a, max: Math.min(10, a + 1 + rnd(2)) }; }, 15],
      [() => { const a = 1 + rnd(9); return seq(a, Math.min(10, a + 1 + rnd(2))); }, 25],
      [() => pick([1, 2, 5, 6, 10]), 25],
    ])();
  },
  start_period: (kind) => (kind === 'prefer'
    ? weighted([
      [() => ({ min: pick([2, 3, 3, 4, 4, 6, 7]) }), 70],
      [() => 1 + rnd(9), 15],
      [() => { const a = 1 + rnd(6); return { min: a, max: a + 1 + rnd(3) }; }, 15],
    ])
    : weighted([
      [() => pick([1, 1, 2, 6, 9]), 45],
      [() => ({ max: pick([1, 2, 2, 3]) }), 35],
      [() => ({ min: pick([8, 9, 10]) }), 20],
    ]))(),
  end_period: (kind, session) => {
    if (session === 'sáng') return kind === 'prefer' ? { max: pick([2, 3, 4]) } : pick([{ min: 5 }, 5]);
    if (session === 'chiều') return kind === 'prefer' ? { max: pick([7, 8, 9]) } : pick([{ min: 9 }, { min: 10 }, 10]);
    return (kind === 'prefer'
      ? weighted([
        [() => ({ max: pick([3, 4, 5, 7, 8, 9]) }), 75],
        [() => 2 + rnd(9), 15],
        [() => { const a = 2 + rnd(6); return { min: a, max: a + 1 + rnd(2) }; }, 10],
      ])
      : weighted([
        [() => ({ min: pick([7, 8, 9, 10]) }), 60],
        [() => pick([5, 9, 10]), 25],
        [() => pick([{ min: 4, max: 5 }, { min: 9, max: 10 }]), 15],
      ]))();
  },
  start_time: (kind, session) => {
    if (session === 'sáng') return kind === 'prefer' ? { min: between('08:00', '10:30') } : { max: between('07:30', '08:30') };
    if (session === 'chiều') return kind === 'prefer' ? { min: between('13:30', '15:00') } : { max: between('13:00', '14:00') };
    return (kind === 'prefer'
      ? weighted([
        [() => ({ min: between('07:30', '14:00') }), 75],
        [() => pick(PERIOD_STARTS), 10],
        [() => { const a = between('07:30', '10:00'); return { min: a, max: later(a, 60, 180) }; }, 15],
      ])
      : weighted([
        [() => ({ max: between('07:00', '09:30') }), 70],
        [() => pick(['07:30', '13:00']), 15],
        [() => ({ min: between('15:00', '17:00') }), 15],
      ]))();
  },
  end_time: (kind, session) => {
    if (session === 'sáng') return kind === 'prefer' ? { max: between('10:00', '12:00') } : { min: between('11:00', '12:00') };
    if (session === 'chiều') return kind === 'prefer' ? { max: between('15:00', '17:00') } : { min: between('16:00', '18:00') };
    return (kind === 'prefer'
      ? weighted([
        [() => ({ max: between('10:00', '17:30') }), 85],
        [() => { const a = between('10:00', '15:00'); return { min: a, max: later(a, 60, 120) }; }, 15],
      ])
      : weighted([
        [() => ({ min: between('15:30', '18:00') }), 85],
        [() => { const a = between('11:00', '12:00'); return { min: a, max: later(a, 30, 60) }; }, 15],
      ]))();
  },
  // Lớp trong dữ liệu dài 2–4 tiết
  duration: (kind) => (kind === 'prefer'
    ? weighted([
      [() => pick([2, 3]), 40], [() => ({ max: pick([2, 3]) }), 30], [() => ({ min: 2, max: 3 }), 20], [() => ({ min: 3 }), 10],
    ])
    : weighted([[() => ({ min: pick([3, 4, 4]) }), 60], [() => pick([2, 4, 4]), 40]]))(),
  area: () => weighted([['K', 60], ['V', 40]]),
  room: (kind) => {
    const area = weighted([['K', 75], ['V', 25]]);
    const k = weighted([[1, kind === 'prefer' ? 75 : 80], [2, kind === 'prefer' ? 25 : 20]]);
    const rooms = sample(cfg.rooms[area], k).map((r) => (Math.random() < 0.35 ? `${area}.${r}` : r));
    return rooms.length === 1 ? rooms[0] : rooms;
  },
};

// Cận của limit; phrase = câu không nêu số (llm-guide mục 3: "trải đều", "dồn lịch")
const LIMIT_GEN = {
  subjects_per_day: () => weighted([
    [() => ({ value: { max: pick([1, 2, 2, 2, 3]) } }), 70], [() => ({ value: { min: 2 } }), 10],
    [() => ({ value: { min: 1, max: 2 } }), 10], [() => ({ value: { max: 1 }, phrase: 'trải đều' }), 10],
  ])(),
  subjects_per_session: () => weighted([
    [() => ({ value: { max: 1 } }), 60], [() => ({ value: { max: 2 } }), 25], [() => ({ value: { min: 2 } }), 15],
  ])(),
  periods_per_day: () => weighted([
    [() => ({ value: { max: pick([4, 5, 6, 6, 7, 8]) } }), 70], [() => ({ value: { min: pick([3, 4, 5]) } }), 15],
    [() => ({ value: pick([{ min: 4, max: 6 }, { min: 3, max: 5 }]) }), 15],
  ])(),
  gap_periods: () => weighted([
    [() => ({ value: { min: 1 } }), 35], [() => ({ value: { min: 1 }, phrase: 'có nghỉ' }), 15], [() => ({ value: { min: 2 } }), 10],
    [() => ({ value: { max: 0 } }), 20], [() => ({ value: { max: pick([1, 2]) } }), 20],
  ])(),
  consecutive_periods: () => ({ value: { max: pick([3, 4, 4, 5, 6]) } }),
  study_days: () => weighted([
    [() => ({ value: { max: pick([2, 3, 3, 4]) } }), 60], [() => ({ value: { min: pick([4, 5]) } }), 15],
    [() => ({ value: { min: 3, max: 4 } }), 10], [() => ({ value: { max: 1 }, phrase: 'dồn lịch' }), 15],
  ])(),
};

function makeUnsupportedSlot() {
  const theme = pick(cfg.unsupportedThemes);
  const [c1, c2] = sample(pools.all, 2).map((c) => c.name);
  const fill = { c1, c2 };
  const text = theme.text.replace(/\{(\w+)\}/g, (_, k) => {
    if (!(k in fill)) fill[k] = pick(cfg.unsupportedFill[k]);
    return fill[k];
  });
  // say: các giá trị câu phải nêu nguyên văn (tên bạn, mã lớp, tên môn)
  return { level: null, scope: null, theme: theme.name, text, re: theme.re, say: (theme.say || []).map((k) => fill[k]),
    areaOk: !!theme.areaOk, teacherOk: !!theme.teacherOk };
}

function makeSlot() {
  if (t.kind === 'unsupported') return makeUnsupportedSlot();
  const level = weighted(cfg.levelWeights);
  const where = weighted(cfg.scopePlan[t.attr]);
  let scope = null;
  let value = null;
  let teacher = null;
  let phrase = null;
  if (t.kind === 'limit') {
    if (where === 'day') scope = { day: pick(SCHOOL_DAYS) };
    if (where === 'session') scope = { session: pick(['sáng', 'chiều']) };
    ({ value, phrase = null } = LIMIT_GEN[t.attr]());
    if (phrase && t.attr !== 'gap_periods') scope = null; // "trải đều", "dồn lịch" nói về cả tuần
  } else if (t.attr === 'teacher') {
    const c = pick(pools.teacher);
    teacher = pick(c.teachers);
    if (where === 'course') scope = { course: c.name };
  } else if (t.attr === 'class_group') {
    const c = pick(pools.group);
    const max = where === 'course' ? c.maxGroup : 10;
    value = Math.random() < 0.75 ? 1 + rnd(max) : distinct(2, () => 1 + rnd(max)).sort((a, b) => a - b);
    if (where === 'course') scope = { course: c.name };
  } else {
    if (where === 'course') scope = { course: pick(t.attr === 'language' ? pools.english : pools.all).name };
    if (where === 'day') scope = { day: pick(SCHOOL_DAYS) };
    if (where === 'session') scope = { session: pick(['sáng', 'chiều']) };
    value = GEN[t.attr](t.kind, scope && scope.session);
  }
  return { level, scope, value, teacher, phrase };
}

// ---------- Mô tả slot cho AI ----------
const LEVEL_TEXT = {
  normal: {
    prefer: 'normal — từ nhẹ: muốn, thích, ưu tiên, mong, nếu được, nếu có thể',
    avoid: 'normal — từ nhẹ: không muốn, không thích, tránh, hạn chế, nếu được thì đừng',
    limit: 'normal — không dùng từ khoá mức độ; được dùng "tối đa", "ít nhất", "không quá", "muốn", "nếu được"',
  }[t.kind],
  high: 'high — phải có một trong: "rất muốn", "rất cần", "rất mong", "rất không muốn", "quan trọng nhất", "ưu tiên hàng đầu"',
  must: 'must — phải có một trong: "chỉ", "bắt buộc", "phải", "không thể", "nhất định", "tuyệt đối"',
};

function scopeText(scope) {
  if (!scope) return 'toàn bộ lịch (không nhắc môn, thứ hay buổi nào)';
  if (scope.course) return `môn "${scope.course}" (nêu đúng tên môn này)`;
  if (scope.day) return `các lớp vào ${scope.day}`;
  return `các lớp buổi ${scope.session}`;
}

function timeSay(hm) {
  const [h, m] = hm.split(':').map(Number);
  const forms = [`${h}h${m ? String(m).padStart(2, '0') : ''}`, `${h} giờ${m ? ` ${m}` : ''}`];
  if (h > 12) forms.push(`${h - 12} giờ${m ? ` ${m}` : ''} chiều`);
  return forms.map((f) => `"${f}"`).join(' / ');
}

const SESSION_TEXT = {
  'sáng': 'buổi sáng (câu nói "sáng" hoặc "buổi sáng")',
  'chiều': 'buổi chiều (câu nói "chiều" hoặc "buổi chiều")',
  'sáng sớm': 'sáng sớm (câu phải có cụm "sáng sớm", không nói tiết)',
  'chiều muộn': 'chiều muộn (câu phải có cụm "chiều muộn" hoặc "cuối buổi chiều", không nói tiết)',
};

function periodBound(v) {
  const start = t.attr === 'start_period';
  const verb = start ? 'bắt đầu' : 'kết thúc';
  if (typeof v === 'number') return `lớp ${verb} đúng ở tiết ${v} (viết "${verb} ở tiết ${v}")`;
  if (v.min != null && v.max != null) return `lớp ${verb} trong khoảng tiết ${v.min} đến tiết ${v.max}`;
  if (v.min != null) {
    return start
      ? `lớp bắt đầu từ tiết ${v.min} trở đi (viết "từ tiết ${v.min}" hoặc "không sớm hơn tiết ${v.min}"; KHÔNG viết "sau tiết …")`
      : `lớp kết thúc từ tiết ${v.min} trở đi (viết "học tới tiết ${v.min}" hoặc "kết thúc ở tiết ${v.min} hoặc muộn hơn")`;
  }
  const before = v.max < 10 ? `"${start ? 'bắt đầu' : 'xong'} trước tiết ${v.max + 1}" hoặc ` : '';
  return start
    ? `lớp bắt đầu muộn nhất ở tiết ${v.max} (viết ${before}"bắt đầu muộn nhất tiết ${v.max}")`
    : `lớp kết thúc muộn nhất ở tiết ${v.max} (viết ${before}"học đến tiết ${v.max} là xong")`;
}

function timeBound(v) {
  const start = t.attr === 'start_time';
  const verb = start ? 'bắt đầu' : 'kết thúc';
  if (typeof v === 'string') return `lớp ${verb} lúc ${v} (giờ viết ${timeSay(v)})`;
  if (v.min && v.max) return `lớp ${verb} trong khoảng ${v.min} đến ${v.max} (giờ viết như ${timeSay(v.min)} … ${timeSay(v.max)})`;
  if (v.min) return `lớp ${verb} sau ${v.min} (viết "${start ? 'bắt đầu' : 'kết thúc'} sau …" hoặc "từ … trở đi"; giờ viết ${timeSay(v.min)})`;
  return start
    ? `lớp bắt đầu trước ${v.max} (viết "bắt đầu trước …" hoặc "học trước …"; giờ viết ${timeSay(v.max)})`
    : `lớp kết thúc trước ${v.max} (viết "về trước …", "tan học trước …" hoặc "xong trước …"; giờ viết ${timeSay(v.max)})`;
}

function durationText(v) {
  if (typeof v === 'number') return `lớp dài ${v} tiết (viết "lớp ${v} tiết", số đứng trước chữ "tiết")`;
  if (v.min != null && v.max != null) return `lớp dài từ ${v.min} đến ${v.max} tiết (viết "lớp ${v.min}-${v.max} tiết" hoặc "từ ${v.min} đến ${v.max} tiết")`;
  if (v.min != null) return `lớp dài từ ${v.min} tiết trở lên (viết "từ ${v.min} tiết trở lên" hoặc "ít nhất ${v.min} tiết")`;
  return `lớp dài tối đa ${v.max} tiết (viết "tối đa ${v.max} tiết" hoặc "không quá ${v.max} tiết")`;
}

// Cận của limit, số viết bằng chữ số, đúng các số của slot
function boundText(v, unit) {
  if (v.min != null && v.max != null) return `từ ${v.min} đến ${v.max} ${unit} (viết "${v.min}-${v.max} ${unit}" hoặc "từ ${v.min} đến ${v.max} ${unit}")`;
  if (v.min != null) return `ít nhất ${v.min} ${unit} (viết "ít nhất ${v.min} ${unit}", "tối thiểu ${v.min} ${unit}" hoặc "từ ${v.min} ${unit} trở lên")`;
  return `tối đa ${v.max} ${unit} (viết "tối đa ${v.max} ${unit}", "không quá ${v.max} ${unit}" hoặc "nhiều nhất ${v.max} ${unit}")`;
}

function limitText(s) {
  const v = s.value;
  // Có phạm vi thứ / buổi thì câu không cần chữ "ngày" / "buổi"
  const day = s.scope && s.scope.day ? '' : ' và "ngày"';
  const session = s.scope && s.scope.session ? '' : ' và "buổi"';
  switch (t.attr) {
    case 'subjects_per_day':
      if (s.phrase) return 'lịch học trải đều trong tuần (câu phải có "trải đều" hoặc "rải đều", không nêu số)';
      return `số môn học trong mỗi ngày: ${boundText(v, 'môn')}; câu nói "môn"${day}, không nói "buổi" hay "tiết"`;
    case 'subjects_per_session':
      return `số môn học trong mỗi buổi: ${boundText(v, 'môn')}; câu nói "môn"${session}, không nói "tiết"`;
    case 'periods_per_day':
      return `tổng số tiết học trong mỗi ngày: ${boundText(v, 'tiết')}; câu nói "tiết"${day}, không nói "môn", không nói "liền"/"liên tục"`;
    case 'gap_periods':
      if (s.phrase) return 'có thời gian nghỉ giữa các môn trong ngày (câu phải có chữ "nghỉ", không nêu số)';
      if (v.max === 0) return 'không có tiết trống giữa hai môn liền nhau (viết kiểu "không muốn có tiết trống giữa các môn", không nêu số, không dùng "liền"/"liên tục")';
      return `số tiết trống (nghỉ) giữa hai môn liền nhau: ${boundText(v, 'tiết')}; câu có chữ "nghỉ" hoặc "trống", không dùng "liền"/"liên tục"`;
    case 'consecutive_periods':
      return `số tiết học liên tục không nghỉ: ${boundText(v, 'tiết')}; câu phải có "liền", "liên tục" hoặc "liên tiếp"`;
    default: // study_days
      if (s.phrase) return 'dồn lịch vào ít ngày nhất (câu phải có chữ "dồn", không nêu số)';
      return `số ngày phải lên trường mỗi tuần: ${boundText(v, 'ngày')}; câu nói "ngày", không nói "môn" hay "tiết"`;
  }
}

function condText(s) {
  const v = s.value;
  if (t.kind === 'limit') return limitText(s);
  switch (t.attr) {
    case 'unsupported':
      return s.text;
    case 'duration':
      return durationText(v);
    case 'area':
      return `học ở khu ${v} (viết "khu ${v}" hoặc "khu vực ${v}")`;
    case 'room': {
      const list = Array.isArray(v) ? v : [v];
      return `học ở phòng ${list.join(t.kind === 'prefer' ? ' hoặc ' : ' và ')} (viết đúng mã phòng như trên, kèm chữ "phòng"; không nhắc khu riêng)`;
    }
    case 'teacher': {
      const w = s.teacher.split(' ');
      return `học với giảng viên ${s.teacher} (gọi theo cách sinh viên hay gọi: họ tên đầy đủ, "${w.slice(-2).join(' ')}" hoặc "${w[w.length - 1]}", có thể thêm "thầy"/"cô")`;
    }
    case 'class_group':
      return Array.isArray(v) ? `nhóm ${v[0]} ${t.kind === 'prefer' ? 'hoặc' : 'và'} nhóm ${v[1]}` : `nhóm ${v}`;
    case 'language':
      return `lớp dạy bằng ${v}`;
    case 'day': {
      if (v === 'cuối tuần') return 'học vào cuối tuần (câu phải có cụm "cuối tuần")';
      if (v === 'ngày thường') return 'học vào ngày thường, thứ 2 đến thứ 6 (câu phải có cụm "ngày thường" hoặc "các ngày trong tuần")';
      const list = Array.isArray(v) ? v : [v];
      return `học vào ${list.join(t.kind === 'prefer' ? ' hoặc ' : ' và ')} (có thể viết "thứ 4", "thứ Tư", "T4"…)`;
    }
    case 'session':
      return `học ${SESSION_TEXT[v]}`;
    case 'periods':
      if (typeof v === 'number') return `học tiết ${v}`;
      if (Array.isArray(v)) return `học các tiết ${v.join(', ')} (liệt kê từng tiết)`;
      return `học trong khoảng tiết ${v.min} đến tiết ${v.max} (viết "từ tiết ${v.min} đến tiết ${v.max}" hoặc "tiết ${v.min}-${v.max}")`;
    case 'start_period':
    case 'end_period':
      return periodBound(v);
    default:
      return timeBound(v);
  }
}

const nSlots = need + Math.ceil(need / 5); // dư một ít để bù câu bị loại
const slots = Array.from({ length: nSlots }, makeSlot);
const style = cfg.styles[(attempt - 1 + t.stt) % cfg.styles.length];

const KIND_TEXT = { prefer: 'MUỐN', avoid: 'TRÁNH', limit: 'GIỚI HẠN', unsupported: 'Ý KHÔNG HỖ TRỢ' };
const lines = slots.map((s, i) => (t.kind === 'unsupported'
  ? `${i + 1}. ${KIND_TEXT[t.kind]}: ${condText(s)}`
  : [
    `${i + 1}. mức độ: ${LEVEL_TEXT[s.level]}`,
    `   phạm vi: ${scopeText(s.scope)}`,
    `   ${KIND_TEXT[t.kind]}: ${condText(s)}`,
  ].join('\n')));

const shown = sample(existing, 25);
const prompt = [
  `LOẠI: ${t.key} — ${t.desc}`,
  `PHONG CÁCH LẦN NÀY: ${style.text}`,
  '',
  `Viết đúng ${nSlots} câu, câu thứ i ứng với slot i:`,
  ...lines,
  '',
  shown.length ? `Đã có ${count} câu cho loại này. Không viết lại hay chỉ đổi vài chữ của các câu sau:\n${shown.map((s) => `- ${s}`).join('\n')}\n` : '',
  `Trả về đúng một JSON array ${nSlots} phần tử: [{"slot": 1, "sentence": "..."}, ...]`,
].join('\n');

return [{ json: { ...base, style: style.name, slots, existing, prompt } }];

// Đọc JSON array AI trả về, kiểm tra từng câu theo slot của nó và tạo các dòng để ghi vào tab.
// Câu bị loại được ghi kèm lý do trong `rejected` (xem ở output của node này).
const settings = $('Settings').first().json;
const cfg = $('Dataset Config').first().json;
const t = $('Current Type').first().json;
const ctx = $('Compute Batch').first().json;
const agent = $input.first().json;

const HEADER = ['id', 'type', 'sentence', 'style', 'model', 'created_at'];

// ---------- Chuẩn hoá chuỗi ----------
// fold: bỏ dấu, chữ thường, chỉ giữ chữ/số; low: giữ dấu, bỏ dấu câu. Cả hai có khoảng trắng hai đầu.
const fold = (s) => ` ${String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[đĐ]/g, 'd')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()} `;
const low = (s) => ` ${String(s).normalize('NFC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim()} `;
const norm = (s) => low(s).trim();

function extractArray(raw) {
  if (Array.isArray(raw)) return raw;
  const text = String(raw || '').replace(/```(?:json)?/gi, '');
  const a = text.indexOf('[');
  const b = text.lastIndexOf(']');
  if (a < 0 || b <= a) return [];
  try {
    const v = JSON.parse(text.slice(a, b + 1));
    return Array.isArray(v) ? v : [];
  } catch (e) {
    return [];
  }
}

// ---------- Từ khoá ----------
const MUST_RE = / (chỉ|bắt buộc|phải|không thể|nhất định|tuyệt đối|nhất quyết) /;
const NOT_MUST_RE = / (không phải|chẳng phải|đâu phải|phải không|phải chăng) /g;
const HIGH_RE = / rất (không )?(muốn|cần|mong) | quan trọng nhất | ưu tiên hàng đầu | ưu tiên số (1|một) | ưu tiên cao nhất /;
const INTENSE_RE = / (rất|cực kỳ|cực kì|vô cùng|hết sức) (không )?(muốn|cần|mong|thích|ghét|ngại|sợ|ưng) /;
const NEG_RE = / (không|ko|chẳng|chả|đừng|tránh|né|hạn chế|ngại|ghét|khỏi) /;
const PREFER_NEG_RE = / (không|ko|chẳng|chả|đừng) (muốn|thích|học|ưng|mong|xếp|cho) | tránh | né | ghét | ngại /;
const TEACHER_WORD_RE = / (thầy|cô|giảng viên|gv) /;
const PERIOD_WORD_RE = / tiết /;
const TIME_RE = /\d{1,2}\s*(giờ|h\d{0,2}|g\d{0,2})(?!\p{L})|\d{1,2}:\d{2}/u;
const PERIOD_ATTRS = ['periods', 'start_period', 'end_period', 'duration'];
const MIN_DIR_RE = / (ít nhất|tối thiểu|trở lên) /;
const MAX_DIR_RE = / (tối đa|không quá|nhiều nhất|trở xuống) /;
const CONTINUOUS_RE = / (liền|liên tục|liên tiếp) /;

// Phòng (trên chuỗi gốc): "A212", "V.A201" → viết hoa
const roomsIn = (s) => [...s.matchAll(/(?<![\p{L}\p{N}.])(?:[kv]\.)?[abc]\d{3}(?!\p{N})/giu)].map((m) => m[0].toUpperCase());
// Khu (trên chuỗi fold): "khu K", "khu vực V"
const areasIn = (f) => new Set([...f.matchAll(/ khu (?:vuc )?([kv])(?= )/g)].map((m) => m[1].toUpperCase()));

// Thứ (trên chuỗi fold)
const DAY_RE = {
  'thứ 2': / thu (2|hai) | t2 /, 'thứ 3': / thu (3|ba) | t3 /, 'thứ 4': / thu (4|tu) | t4 /,
  'thứ 5': / thu (5|nam) | t5 /, 'thứ 6': / thu (6|sau) | t6 /, 'thứ 7': / thu (7|bay) | t7 /,
  'chủ nhật': / chu nhat | cn /,
};
const DAY_GROUP_RE = { 'cuối tuần': / cuoi tuan /, 'ngày thường': / ngay thuong | cac ngay trong tuan / };
const WEEKDAY_KEYS = ['thứ 2', 'thứ 3', 'thứ 4', 'thứ 5', 'thứ 6'];
const daysIn = (f) => Object.keys(DAY_RE).filter((d) => DAY_RE[d].test(f));
const anyDayGroup = (f) => Object.values(DAY_GROUP_RE).some((re) => re.test(f));

// Buổi (trên chuỗi low)
function sessionsIn(l) {
  const found = new Set();
  let rest = l.replace(/ tối (đa|thiểu) /g, ' ');
  if (/ (sáng sớm|đầu buổi sáng|sáng thật sớm) /.test(rest)) { found.add('sáng sớm'); rest = rest.replace(/ (sáng sớm|đầu buổi sáng|sáng thật sớm) /g, ' '); }
  if (/ (chiều muộn|cuối buổi chiều|cuối chiều) /.test(rest)) { found.add('chiều muộn'); rest = rest.replace(/ (chiều muộn|cuối buổi chiều|cuối chiều) /g, ' '); }
  if (/ sáng /.test(rest)) found.add('sáng');
  if (/ chiều /.test(rest)) found.add('chiều');
  if (/ (trưa|tối) /.test(rest)) found.add('khác');
  return found;
}
const sameSet = (a, b) => a.size === b.size && [...a].every((x) => b.has(x));

// Tên môn để phát hiện câu nhắc môn khi không có phạm vi môn. So có dấu: "Học sâu" ≠ "học sau 10 giờ"
const courseNames = cfg.courses.map((c) => low(c[0])).filter((n) => n.trim().length >= 6);

// Các số trong câu (chuỗi fold), bỏ số của "thứ 2"; "9h30" → 9, 30; "T2" không tính
function numbersIn(f) {
  const toks = f.trim().split(' ');
  const out = new Set();
  toks.forEach((tok, i) => {
    if (toks[i - 1] === 'thu') return;
    if (/^\d+$/.test(tok)) out.add(Number(tok));
    else if (/^\d+[hg]\d*$/.test(tok)) tok.match(/\d+/g).forEach((d) => out.add(Number(d)));
  });
  return out;
}
const hourForms = (hm) => { const h = Number(hm.split(':')[0]); return h > 12 ? [h, h - 12] : [h]; };

// Số chỉ lượng (duration, limit): bỏ số của "thứ 2", "1 tuần", và "1 ngày"/"1 buổi" khi nghĩa là "mỗi"
function valueNumbersIn(f, unit) {
  const toks = f.trim().split(' ');
  const out = new Set();
  toks.forEach((tok, i) => {
    if (!/^\d+$/.test(tok) || toks[i - 1] === 'thu') return;
    const next = toks[i + 1];
    if (next === 'tuan' || (tok === '1' && ['ngay', 'buoi'].includes(next) && next !== unit)) return;
    out.add(Number(tok));
  });
  return out;
}

// Số và từ chỉ hướng phải khớp cận: v là số, hoặc {min, max}; cận 0 không cần nêu số
function boundsCheck(v, nums, l) {
  const want = typeof v === 'number' ? [v] : [v.min, v.max].filter((x) => x != null && x !== 0);
  const ok = want.length ? sameSet(nums, new Set(want)) : [...nums].every((n) => n === 0);
  if (!ok) return `số trong câu (${[...nums].join(', ') || 'không có'}) khác slot (${want.join(', ') || 'không số'})`;
  if (typeof v === 'number') {
    if (MIN_DIR_RE.test(l) || MAX_DIR_RE.test(l)) return 'có "ít nhất/tối đa" nhưng slot là một số';
  } else if (v.min == null && MIN_DIR_RE.test(l)) {
    return 'có "ít nhất/trở lên" nhưng slot chỉ có cận trên';
  } else if (v.max == null && MAX_DIR_RE.test(l)) {
    return 'có "tối đa/không quá" nhưng slot chỉ có cận dưới';
  }
  return null;
}

// limit: từ chỉ đơn vị bắt buộc / bị cấm của từng chỉ số; phrase = cụm của câu không nêu số.
// Phạm vi thứ thay cho chữ "ngày", phạm vi buổi thay cho chữ "buổi" ("Thứ 2 tối đa 2 môn").
const DAY_WORD_RE = / ngày /;
const SESSION_WORD_RE = / buổi /;
const LIMIT_RULES = {
  subjects_per_day: { unit: 'mon', need: [/ môn /, DAY_WORD_RE], forbid: / (buổi|tiết) /, phrase: / (trải|rải) đều / },
  subjects_per_session: { unit: 'mon', need: [/ môn /, SESSION_WORD_RE], forbid: / tiết / },
  periods_per_day: { unit: 'tiet', need: [/ tiết /, DAY_WORD_RE], forbid: / (môn|liền|liên tục|liên tiếp) / },
  gap_periods: { unit: 'tiet', need: [/ (nghỉ|trống) /], forbid: CONTINUOUS_RE, phrase: / nghỉ / },
  consecutive_periods: { unit: 'tiet', need: [/ tiết /, CONTINUOUS_RE], forbid: / trống / },
  study_days: { unit: 'ngay', need: [/ ngày /], forbid: / (môn|tiết) /, phrase: / dồn / },
};

function checkLimit(slot, l, f) {
  const r = LIMIT_RULES[t.attr];
  const nums = valueNumbersIn(f, r.unit);
  if (r.forbid.test(l)) return 'có từ của chỉ số khác';
  if (slot.phrase) {
    if (!r.phrase.test(l)) return `thiếu cụm "${slot.phrase}"`;
    return nums.size ? 'slot không nêu số nhưng câu có số' : null;
  }
  const scope = slot.scope || {};
  const need = r.need.filter((re) => !(re === DAY_WORD_RE && scope.day) && !(re === SESSION_WORD_RE && scope.session));
  if (need.some((re) => !re.test(l))) return 'thiếu từ chỉ đơn vị của chỉ số';
  return boundsCheck(slot.value, nums, l);
}

// unsupported: câu nêu đúng ý của chủ đề, không kèm điều kiện mà schema biểu diễn được
function checkUnsupported(sentence, slot) {
  const f = fold(sentence);
  let rest = f;
  let l = low(sentence);
  let raw = sentence.toLowerCase();
  for (const w of slot.say) {
    if (!f.includes(fold(w))) return `thiếu "${w}"`;
    rest = rest.replace(fold(w), ' ');
    l = l.replace(low(w), ' ');
    raw = raw.replace(w.toLowerCase(), ' ');
  }
  if (!new RegExp(slot.re).test(rest)) return `không thấy ý của chủ đề ${slot.theme}`;
  if (/ (riêng|trừ|ngoại trừ|ngoài ra) /.test(l)) return 'có từ ngoại lệ';
  if (daysIn(rest).length || anyDayGroup(rest)) return 'nhắc thứ';
  if (sessionsIn(l).size) return 'nhắc buổi';
  if (PERIOD_WORD_RE.test(l) || TIME_RE.test(raw)) return 'nhắc tiết/giờ';
  if (courseNames.some((n) => l.includes(n))) return 'nhắc tên môn ngoài slot';
  if (!slot.teacherOk && TEACHER_WORD_RE.test(l)) return 'nhắc giảng viên';
  if (!slot.areaOk && / khu /.test(l)) return 'nhắc khu';
  if (roomsIn(raw).length) return 'nhắc mã phòng';
  return null;
}

// Tên giảng viên: phần đuôi dài nhất của họ tên xuất hiện trong câu ("Mai Nga", "Nga", …)
function teacherAsSaid(full, sentenceFold) {
  const words = full.split(/\s+/);
  for (let k = words.length; k >= 1; k--) {
    const tail = words.slice(-k).join(' ');
    if (sentenceFold.includes(fold(tail))) return tail;
  }
  return null;
}

// Trả về null nếu câu hợp lệ, ngược lại là lý do loại. said: tên giảng viên như trong câu (loại teacher)
function check(sentence, slot, said) {
  const scope = slot.scope || {};
  const lFull = low(sentence);
  const f = fold(sentence);
  const words = lFull.trim().split(' ').length;
  if (words < 4 || words > 45) return `độ dài ${words} từ`;
  if (/[{}\n]|json/i.test(sentence)) return 'có ký tự lạ';
  if (t.kind === 'unsupported') return checkUnsupported(sentence, slot);

  // Phạm vi môn. Các kiểm tra từ khoá chạy trên câu đã bỏ tên môn và tên giảng viên:
  // "Khởi nghiệp và đổi mới sáng tạo" không phải buổi sáng, "(1 tín chỉ)" không phải "chỉ".
  let fNoCourse = f;
  let l = lFull;
  let raw = sentence.toLowerCase();
  if (scope.course) {
    const c = fold(scope.course);
    if (!f.includes(c)) return 'thiếu tên môn của phạm vi';
    fNoCourse = f.replace(c, ' ');
    l = l.replace(low(scope.course), ' ');
    raw = raw.replace(scope.course.toLowerCase(), ' ');
  } else if (courseNames.some((n) => lFull.includes(n))) {
    return 'nhắc tên môn khi phạm vi là toàn bộ lịch';
  }
  if (said) l = l.replace(low(said), ' ');
  if (/ (riêng|trừ|ngoại trừ|ngoài ra) /.test(l)) return 'có từ ngoại lệ';

  // Khu, phòng: chỉ loại area / room được nhắc
  const rooms = roomsIn(raw);
  if (t.attr !== 'room' && rooms.length) return 'nhắc phòng ở loại khác';
  if (t.attr !== 'area' && areasIn(fNoCourse).size) return 'nhắc khu ở loại khác';

  // Mức độ
  const isMust = MUST_RE.test(l.replace(NOT_MUST_RE, ' '));
  const isHigh = HIGH_RE.test(l);
  if (slot.level === 'must' && !isMust) return 'must nhưng thiếu từ khoá must';
  if (slot.level === 'high' && (!isHigh || isMust)) return 'high nhưng thiếu từ khoá high hoặc có từ khoá must';
  if (slot.level === 'normal' && (isMust || isHigh || INTENSE_RE.test(l))) return 'normal nhưng có từ khoá high/must';

  // prefer / avoid
  if (t.kind === 'avoid' && !NEG_RE.test(l)) return 'avoid nhưng không có ý tránh';
  if (t.kind === 'prefer' && PREFER_NEG_RE.test(l)) return 'prefer nhưng viết dạng phủ định';

  // Thứ
  const days = daysIn(fNoCourse);
  if (t.attr === 'day') {
    const v = slot.value;
    if (v === 'cuối tuần' || v === 'ngày thường') {
      if (!DAY_GROUP_RE[v].test(f)) return `thiếu cụm "${v}"`;
      const allowed = v === 'cuối tuần' ? ['thứ 7', 'chủ nhật'] : WEEKDAY_KEYS;
      if (days.some((d) => !allowed.includes(d))) return 'nhắc thêm thứ khác';
    } else {
      const want = new Set(Array.isArray(v) ? v : [v]);
      if (!sameSet(new Set(days), want)) return `thứ trong câu (${days.join(', ') || 'không có'}) khác slot`;
      if (anyDayGroup(f)) return 'nhắc thêm nhóm ngày';
    }
  } else if (scope.day) {
    if (days.length !== 1 || days[0] !== scope.day || anyDayGroup(f)) return 'thứ của phạm vi không khớp';
  } else if (days.length || anyDayGroup(f)) {
    return 'nhắc thứ khi không có phạm vi thứ';
  }

  // Buổi: loại giờ được phép có "10 giờ sáng"
  const sessions = sessionsIn(l);
  const timeAttr = t.attr === 'start_time' || t.attr === 'end_time';
  if (t.attr === 'session') {
    if (!sameSet(sessions, new Set([slot.value]))) return `buổi trong câu (${[...sessions].join(', ') || 'không có'}) khác slot`;
  } else if (scope.session) {
    if (!sessions.has(scope.session) || (!timeAttr && sessions.size !== 1)) return 'buổi của phạm vi không khớp';
  } else if (!timeAttr && sessions.size) {
    return 'nhắc buổi khi không có phạm vi buổi';
  }

  // Đơn vị: giờ ↔ tiết
  const hasPeriod = PERIOD_WORD_RE.test(l);
  const hasTime = TIME_RE.test(raw);
  if (t.kind === 'limit') {
    if (hasTime) return 'giới hạn nhưng có giờ';
  } else if (timeAttr) {
    if (!hasTime || hasPeriod) return 'loại giờ nhưng thiếu giờ hoặc có chữ "tiết"';
  } else if (PERIOD_ATTRS.includes(t.attr)) {
    if (!hasPeriod || hasTime) return 'loại tiết nhưng thiếu chữ "tiết" hoặc có giờ';
  } else if (hasPeriod || hasTime) {
    return 'nhắc tiết/giờ ở loại không liên quan';
  }

  // Giảng viên
  if (t.attr !== 'teacher' && TEACHER_WORD_RE.test(l)) return 'nhắc giảng viên ở loại khác';

  // Số
  const nums = numbersIn(fNoCourse);
  const v = slot.value;
  if (t.attr === 'class_group') {
    const want = new Set(Array.isArray(v) ? v : [v]);
    if (!sameSet(nums, want)) return `số nhóm trong câu (${[...nums].join(', ')}) khác slot`;
  }
  if (t.attr === 'periods') {
    const want = new Set(typeof v === 'number' ? [v] : Array.isArray(v) ? v : [v.min, v.max]);
    if (!sameSet(nums, want)) return `số tiết trong câu (${[...nums].join(', ')}) khác slot`;
    if (/ (trước|sau) tiết /.test(l)) return 'dùng "trước/sau tiết" cho tập tiết';
  }
  if (t.attr === 'start_period' || t.attr === 'end_period') {
    const exact = typeof v === 'number' ? [v] : [];
    const bounds = typeof v === 'number' ? [] : [v.min, v.max].filter((x) => x != null);
    const allowed = new Set([...exact, ...bounds, ...(v.max != null ? [v.max + 1] : [])]);
    if ([...nums].some((n) => !allowed.has(n))) return `số tiết trong câu (${[...nums].join(', ')}) khác slot`;
    if (v.min != null && !nums.has(v.min)) return 'thiếu tiết của cận dưới';
    if (v.max != null && !nums.has(v.max) && !nums.has(v.max + 1)) return 'thiếu tiết của cận trên';
    if (exact.length && !nums.has(exact[0])) return 'thiếu tiết';
    if (/ sau tiết /.test(l)) return 'dùng "sau tiết" (mơ hồ)';
    for (const m of l.matchAll(/ (trước|sớm hơn) tiết (\d+) /g)) {
      if (v.max == null || Number(m[2]) !== v.max + 1) return `"${m[1]} tiết ${m[2]}" không khớp cận trên`;
    }
    for (const m of l.matchAll(/ (từ|tới|đến|muộn nhất|trễ nhất|chậm nhất)( là)? tiết (\d+) /g)) {
      if (![...exact, ...bounds].includes(Number(m[3]))) return `"${m[1]} tiết ${m[3]}" không khớp slot`;
    }
    // Từ chỉ hướng phải khớp loại cận
    const dir = exact.length ? / (từ|trước|sớm hơn|tới|đến|muộn nhất|trễ nhất|chậm nhất)( là)? tiết | trở đi | hoặc (muộn|sớm) hơn /
      : v.max == null ? / không muộn hơn | (trước|muộn nhất|trễ nhất|chậm nhất)( là)? tiết /
        : v.min == null ? / từ tiết | trở đi | không sớm hơn | hoặc muộn hơn / : null;
    if (dir && dir.test(l)) return 'từ chỉ hướng (từ/trước/đến…) không khớp loại cận';
  }
  if (timeAttr) {
    const times = typeof v === 'string' ? [v] : [v.min, v.max].filter(Boolean);
    const allowed = new Set([0]);
    for (const hm of times) { hourForms(hm).forEach((h) => allowed.add(h)); allowed.add(Number(hm.split(':')[1])); }
    if ([...nums].some((n) => !allowed.has(n))) return `số giờ trong câu (${[...nums].join(', ')}) khác slot`;
    if (times.some((hm) => !hourForms(hm).some((h) => nums.has(h)))) return 'thiếu giờ của slot';
    const before = / (trước|muộn nhất|chậm nhất|trễ nhất)( là)?( lúc)? \d/;
    const after = / (sau|từ)( lúc)? \d/;
    const exactT = typeof v === 'string';
    if ((exactT || !v.max) && before.test(l)) return '"trước …" nhưng slot không có cận trên';
    if ((exactT || !v.min) && after.test(l)) return '"sau/từ …" nhưng slot không có cận dưới';
  }

  if (t.attr === 'duration') {
    if (!/ \d+ tiết /.test(l)) return 'thiếu "<số> tiết"';
    if (/ tiết \d+ /.test(l)) return 'có "tiết <số>" (là tập tiết, không phải độ dài lớp)';
    if (/ \d+ tiếng /.test(l)) return 'nói độ dài bằng "tiếng"';
    if (CONTINUOUS_RE.test(l) || / (mỗi|một) ngày /.test(l)) return 'dễ nhầm với limit (liền / mỗi ngày)';
    const err = boundsCheck(v, valueNumbersIn(fNoCourse, 'tiet'), l);
    if (err) return err;
  }
  if (t.kind === 'limit') {
    const err = checkLimit(slot, l, fNoCourse);
    if (err) return err;
  }

  // Giá trị chữ
  if (t.attr === 'language') {
    const want = slot.value === 'tiếng Anh' ? / tieng anh | english / : / tieng viet | vietnamese /;
    const other = slot.value === 'tiếng Anh' ? / tieng viet | vietnamese / : / tieng anh | english /;
    if (!want.test(fNoCourse) || other.test(fNoCourse)) return 'ngôn ngữ trong câu khác slot';
  }
  if (t.attr === 'area') {
    const areas = areasIn(fNoCourse);
    if (!sameSet(areas, new Set([v]))) return `khu trong câu (${[...areas].join(', ') || 'không có'}) khác slot`;
  }
  if (t.attr === 'room') {
    const want = new Set((Array.isArray(v) ? v : [v]).map((r) => r.toUpperCase()));
    if (!sameSet(new Set(rooms), want)) return `phòng trong câu (${rooms.join(', ') || 'không có'}) khác slot`;
    if (!/ phòng /.test(l)) return 'thiếu chữ "phòng"';
  }
  return null;
}

// ---------- AI lỗi: dừng workflow thay vì gọi tiếp ----------
// Hết quota theo ngày thì dừng ngay; lỗi khác (rate limit theo phút, mạng…) dừng khi lỗi liên tiếp
// Settings.maxAiErrorStreak lượt. Câu đã ghi vẫn còn, chạy lại sẽ tiếp tục từ chỗ dừng.
const aiErrorStreak = agent.error ? (ctx.aiErrorStreak || 0) + 1 : 0;
if (agent.error) {
  const msg = String(agent.error.message || agent.error);
  const daily = /PerDay|per day|retry in \d+h/i.test(msg);
  const maxStreak = Number(settings.maxAiErrorStreak) || 3;
  if (daily || aiErrorStreak >= maxStreak) {
    throw new Error(`Dừng ở type ${t.key} (đã có ${ctx.count} câu): ${daily ? 'AI hết quota theo ngày' : `AI lỗi ${aiErrorStreak} lượt liên tiếp`}. `
      + `Chạy lại khi AI dùng được, workflow sẽ tiếp tục từ chỗ dừng. Lỗi: ${msg.slice(0, 300)}`);
  }
}

// ---------- Duyệt kết quả ----------
const items = extractArray(agent.output ?? agent.text);
const seen = new Set(ctx.existing.map(norm));
const accepted = [];
const rejected = [];
if (agent.error) rejected.push({ slot: null, reason: `AI lỗi: ${String(agent.error.message || agent.error).slice(0, 200)}` });
if (!items.length && !agent.error) rejected.push({ slot: null, reason: 'không đọc được JSON array', raw: String(agent.output || '').slice(0, 300) });

for (const it of items) {
  if (accepted.length >= ctx.need) break;
  const slot = ctx.slots[Number(it && it.slot) - 1];
  const sentence = String((it && it.sentence) || '').normalize('NFC').replace(/\s+/g, ' ').trim();
  if (!slot || !sentence) { rejected.push({ slot: it && it.slot, reason: 'thiếu slot/sentence' }); continue; }
  const key = norm(sentence);
  if (seen.has(key)) { rejected.push({ slot: it.slot, sentence, reason: 'trùng' }); continue; }

  const said = t.attr === 'teacher' ? teacherAsSaid(slot.teacher, fold(sentence)) : null;
  let reason = t.attr === 'teacher' && !said ? `không thấy tên giảng viên ${slot.teacher}` : null;
  if (!reason) {
    try { reason = check(sentence, slot, said); } catch (e) { reason = `lỗi kiểm tra: ${e.message}`; }
  }
  if (reason) { rejected.push({ slot: it.slot, sentence, reason }); continue; }

  seen.add(key);
  accepted.push([
    `${t.key}_${String(ctx.count + accepted.length + 1).padStart(4, '0')}`,
    t.key,
    sentence,
    ctx.style,
    settings.modelLabel || '',
    new Date().toISOString(),
  ]);
}

const values = accepted.length ? (ctx.needHeader ? [HEADER, ...accepted] : accepted) : [];
return [{
  json: {
    typeKey: t.key,
    attempt: ctx.attempt,
    aiErrorStreak,
    returned: items.length,
    added: accepted.length,
    rejectedCount: rejected.length,
    rejected,
    rowCount: values.length,
    values,
  },
}];
